import{_ as r}from"./plugin-vue_export-helper-c27b6911.js";import{r as l,o as d,c as o,d as t,b as a,a as e,e as s,f as i}from"./app-dbea6a6b.js";const c={},p=i(`<h1 id="_1、windows-11使用ollama本地部署qwen2-5-14b模型" tabindex="-1"><a class="header-anchor" href="#_1、windows-11使用ollama本地部署qwen2-5-14b模型" aria-hidden="true">#</a> 1、Windows 11使用Ollama本地部署Qwen2.5-14B模型</h1><h2 id="_1-1-硬件环境" tabindex="-1"><a class="header-anchor" href="#_1-1-硬件环境" aria-hidden="true">#</a> 1.1 硬件环境</h2><p>我的方法需要有Nvidia显卡。CUDA对大多数模型来说都是必要的。当然有无Nvidia显卡的部署方法，只是那样需要非常非常大的内存，这里先不考虑。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>
CPU: Ryzen 7 9700X

GPU: RTX 4070ti Super 16G

内存: 64GB

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里只列举了电脑最重要的三个参数，甚至连内存容量都可以不管（当然还是要有一点的），只看CPU和GPU。</p><p>Qwen2.5的14B版本需要占用大约9G显存，小于这个显存大小就不建议部署了。</p><h2 id="_1-2-软件环境" tabindex="-1"><a class="header-anchor" href="#_1-2-软件环境" aria-hidden="true">#</a> 1.2 软件环境</h2><h3 id="_1-2-1-nvidia驱动" tabindex="-1"><a class="header-anchor" href="#_1-2-1-nvidia驱动" aria-hidden="true">#</a> 1.2.1 Nvidia驱动</h3>`,8),u={href:"https://www.nvidia.cn/geforce/drivers/",target:"_blank",rel:"noopener noreferrer"},v=i(`<h3 id="_1-2-2-cuda" tabindex="-1"><a class="header-anchor" href="#_1-2-2-cuda" aria-hidden="true">#</a> 1.2.2 CUDA</h3><p>在安装完Nvidia驱动后，首先打开cmd或者PowerShell，输入命令：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>
nvidia-smi

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>按回车，查看显卡支持的最高CUDA版本。例如，我的是CUDA 12.7。</p>`,4),h={href:"https://developer.nvidia.com/cuda-toolkit",target:"_blank",rel:"noopener noreferrer"},m=e("h3",{id:"_1-2-3-python环境",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#_1-2-3-python环境","aria-hidden":"true"},"#"),a(" 1.2.3 python环境")],-1),b=e("p",null,"为了防止环境污染，我用了anaconda来管理虚拟环境。",-1),_=e("p",null,"首先是下载。",-1),g=e("p",null,"下载方法1：",-1),k={href:"https://www.anaconda.com/download",target:"_blank",rel:"noopener noreferrer"},f=e("p",null,"下载方法2（适用于国内网络环境）：",-1),w={href:"https://mirrors.tuna.tsinghua.edu.cn/anaconda/",target:"_blank",rel:"noopener noreferrer"},x=e("br",null,null,-1),y={href:"https://mirror.nju.edu.cn/anaconda/archive/",target:"_blank",rel:"noopener noreferrer"},q=i(`<p>找到最新的镜像，Windows要选Windows_x86_64.exe后缀的，例如我选的是Anaconda3-2024.10-1-Windows-x86_64.exe这一项。</p><p>下载到后，默认安装即可。<strong>但要注意，要记住自己的安装路径</strong>，可以先复制一下。安装后需要配置环境变量。打开Windows设置，在搜索栏搜索“高级系统设置”，打开，在界面右下角点“环境变量”。环境变量分为两块区域，一块是用户变量，一块是系统变量。在系统变量那栏找到“PATH”项目（也可能是“Path”），双击。在右边点击新建，粘贴上刚才安装anaconda的路径，回车。然后再点一次新建，粘贴上anaconda的路径，再在后面加上“\\Scripts”，回车，保存。例如，我新建的两个条目：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>
C:\\Users\\33398\\anaconda3

C:\\Users\\33398\\anaconda3\\Scripts

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后，打开cmd或PowerShell，输入：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>
conda <span class="token parameter variable">--version</span>

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>命令行会返回当前conda版本号。注意，cmd或PowerShell必须是新打开的，而不能是刚才已经打开过放在后台的。如果成功返回，再输入：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>
conda init

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>等待片刻，命令行最前面会出现(base)的字样。如果失败，可以搜索一下错误原因，可能会需要用户解开Windows的一些安全限制。总之这个配置过程非常简单。</p><p>成功出现(base)后，就要新建用来跑ollama的环境了。ollama最适配的环境是Python3.9，但我试过用Python3.11也可以。为了稳定性，还是用Python3.9来部署。在出现了(base)的命令行中继续输入：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>
conda create <span class="token parameter variable">-n</span> env_name <span class="token assign-left variable">python</span><span class="token operator">=</span><span class="token number">3.9</span>

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其中，“env_name”需要换成自己起的环境名，比如“llama-factory”。等待anaconda下载并创建好环境，就可以切换到这个新建的环境中：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>
conda activate llama-factory

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后，命令行前面就会变成(llama-factory)而不再是(base)。</p><h3 id="_1-2-4-pytorch" tabindex="-1"><a class="header-anchor" href="#_1-2-4-pytorch" aria-hidden="true">#</a> 1.2.4 pytorch</h3>`,14),P={href:"https://pytorch.org/",target:"_blank",rel:"noopener noreferrer"},S=e("p",null,"根据系统版本、CUDA版本选择好后，复制安装命令，在命令行为(llama_factory)前缀的情况下，输入：",-1),C={href:"https://pytorch.org/",target:"_blank",rel:"noopener noreferrer"},U=i(`<div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>
pip3 <span class="token function">install</span> torch torchvision torchaudio --index-url https://download.pytorch.org/whl/cu126

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>等待安装即可。</p><h3 id="_1-2-5-git" tabindex="-1"><a class="header-anchor" href="#_1-2-5-git" aria-hidden="true">#</a> 1.2.5 git</h3>`,3),A={href:"https://git-scm.com/",target:"_blank",rel:"noopener noreferrer"},D=i(`<p>重新打开cmd或PowerShell，输入</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>
<span class="token function">git</span> <span class="token parameter variable">-v</span>

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>看是否返回git的版本。</p><p>这个记录里，git主要用在llama-factory的拉取。有些模型也需要通过git拉取。</p><h3 id="_1-2-6-用ollama自动下载模型并部署" tabindex="-1"><a class="header-anchor" href="#_1-2-6-用ollama自动下载模型并部署" aria-hidden="true">#</a> 1.2.6 用ollama自动下载模型并部署</h3><p>终于到了这一步！ollama提供的部署方法非常非常简单，只是配置前面这些环境比较麻烦。</p>`,6),N={href:"https://ollama.com/",target:"_blank",rel:"noopener noreferrer"},B=i(`<p>重新打开cmd或PowerShell，进入llama-factory环境。</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>
conda activate llama-factory

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输入命令</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>
ollama run qwen2.5:14b

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>等待，等镜像下好，他就会自动运行了。可以在命令窗口直接和刚部署的AI对话。如果关闭命令窗口后需要重新打开对话框，还是需要进入llama-factory环境，输入ollama run命令运行。</p><p>如果只需要对话功能，事情到这里就结束了。</p><h3 id="_1-2-7-更好的对话框" tabindex="-1"><a class="header-anchor" href="#_1-2-7-更好的对话框" aria-hidden="true">#</a> 1.2.7 更好的对话框</h3><p>如果需要类似于ChatGPT的界面，可以用docker部署webui。使用webui还有一个好处：可以保存每次对话的记录，以后打开可以继续聊。</p><p>使用docker需要打开CPU的虚拟化功能。某些BIOS是不会默认打开的。重启进入BIOS，根据主板品牌不同会有不同的进入方法，需要先查主板的说明书，或者重启出现主板LOGO的时候看一下左下或者右下角有没有进入BIOS按键的提示。虚拟化可以自己找一下打开选项的位置，也可以直接找教程，很简单。</p>`,9),G={href:"https://www.docker.com/",target:"_blank",rel:"noopener noreferrer"},I=i(`<p>安装后，首先需要在直接打开桌面图标，Docker Desktop。docker启动需要一些时间。启动完成后，用<strong>管理员身份</strong>打开cmd或PowerShell，输入命令：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>
<span class="token function">docker</span> <span class="token parameter variable">--version</span>

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果返回版本号，那就是安装成功。</p><p>继续打开Docker Desktop，我们需要先换源（如果有代理可以不用）。点击右上角的齿轮，再在左侧点击Docker Engine。仿照json的格式，加入新项目：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code>
        <span class="token punctuation">{</span>
            <span class="token property">&quot;builder&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
              <span class="token property">&quot;gc&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
                <span class="token property">&quot;defaultKeepStorage&quot;</span><span class="token operator">:</span> <span class="token string">&quot;20GB&quot;</span><span class="token punctuation">,</span>
                <span class="token property">&quot;enabled&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span>
              <span class="token punctuation">}</span>
            <span class="token punctuation">}</span><span class="token punctuation">,</span>
            <span class="token property">&quot;experimental&quot;</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span>
            <span class="token property">&quot;features&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
              <span class="token property">&quot;buildkit&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span>
            <span class="token punctuation">}</span><span class="token punctuation">,</span>
            <span class="token property">&quot;registry-mirrors&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
              <span class="token string">&quot;https://1nj0zren.mirror.aliyuncs.com&quot;</span><span class="token punctuation">,</span>
              <span class="token string">&quot;https://docker.mirrors.ustc.edu.cn&quot;</span><span class="token punctuation">,</span>
              <span class="token string">&quot;http://f1361db2.m.daocloud.io&quot;</span><span class="token punctuation">,</span>
              <span class="token string">&quot;https://registry.docker-cn.com&quot;</span>
      <span class="token punctuation">]</span>
<span class="token punctuation">}</span>

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>保存即可。注意不要改错。如果格式有问题，docker会提示，并且不能保存。改好后，要重新启动一下docker。</p><p>我已经编辑好了启动webui的命令，要用管理员身份运行cmd或者PowerShell，运行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>
<span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">-p</span> <span class="token number">3000</span>:8080 --add-host<span class="token operator">=</span>host.docker.internal:host-gateway <span class="token parameter variable">-v</span> open-webui:/app/backend/data <span class="token parameter variable">--name</span> open-webui <span class="token parameter variable">--restart</span> always ghcr.io/open-webui/open-webui:main

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>首次运行时，docker会因为找不到镜像而去拉取。耐心等待拉取完毕，然后再运行一次这条命令就行。</p><p>打开浏览器，输入网址：127.0.0.1:3000</p><p>就可以顺利打开webui了。首次打开需要注册，当然，这是保存在本地的，所以邮箱是什么其实无所谓，能记住就行，不必非得是真的邮箱。</p><p>进入页面后，就可以正常聊天了。</p><p>至此，好看的对话框界面也搞定了。</p><h3 id="_1-2-9-把服务转发到公网" tabindex="-1"><a class="header-anchor" href="#_1-2-9-把服务转发到公网" aria-hidden="true">#</a> 1.2.9 把服务转发到公网</h3><p>占位</p><h3 id="_1-2-10-在魔搭社区挑选模型并使用llama-factory微调" tabindex="-1"><a class="header-anchor" href="#_1-2-10-在魔搭社区挑选模型并使用llama-factory微调" aria-hidden="true">#</a> 1.2.10 在魔搭社区挑选模型并使用llama-factory微调</h3><p>时间不早，微调下次再写。</p>`,17);function W(O,T){const n=l("ExternalLinkIcon");return d(),o("div",null,[t(" more "),a("我最早接触大模型是在2022年的10月。当时因为疫情被封在家里不能去学校，就在家里尝试推进Quantum Espresso第一性原理计算项目，它是我硕士毕业论文使用到的重要工具。尽管在中国大陆完全没有宣发，但我还是了解到并认真用了一下刚出的ChatGPT3.0。作为第一批开放给普通民众的大模型，它颠覆了我对人工智能的认知，我看到了它广阔的前景，但我一直不懂为什么，我感觉和它之间一直隔着一堵墙。我能明显感觉到，我不能完美地利用这种工具。有人给出了答案——AI作为一种工具，它的能力并非增长人的能力，而是放大人的能力。换言之，如果我原本不具备过硬的能力，那我就不能完全发挥它的能力，毕竟零乘以任何数也还是零。我不能，但总有人能。例如，从那以后，提示词工程师Prompt Engineer作为一种新职业发展了起来，但现在似乎又在被迅速取代——人们发现有时可以让AI帮忙写Prompt，然后反过来喂给AI。在起了个大早后，我再一次赶了个晚集，就像过去那样。所以，趁着这次DeepSeek的崛起，我也想，既然我不能发挥工具的效用，我还可以帮助他人搭建起工具，让他们的能力放大啊！所以前段时间（大概两个月前），我在自己的电脑（Windows 11，RTX 4070Ti Super 16G）、服务器（Ubuntu 24.04，2080ti 22G）上，利用Ollama本地部署了一下阿里的通义千问（Qwen2.5-14B）模型，并用魔搭社区提供的模型和llama-factory尝试了一下自己微调模型（LoRA）。没有Nvidia显卡的电脑还可以用llama.cpp，那个好像更方便。所以，我这里记录的这个方法可能过时了，这里只做记录，之后再更新llama.cpp部署DeepSeek的方法。 "),p,e("p",null,[a("访问"),e("a",u,[a("Nvidia官网驱动搜索"),s(n)]),a("，按照自己的显卡挑选驱动，默认安装即可。")]),v,e("p",null,[a("然后，同样是访问"),e("a",h,[a("Nvidia官网"),s(n)]),a("下载安装即可。虽然我的显卡最高支持到CUDA 12.7，但我下载的是12.6。")]),m,b,_,g,e("p",null,[a("访问"),e("a",k,[a("anaconda官网"),s(n)]),a("下载，默认安装。")]),f,e("p",null,[a("访问"),e("a",w,[a("清华镜像源"),s(n)]),x,a(" 或者"),e("a",y,[a("南大镜像源"),s(n)])]),q,e("p",null,[a("首先访问"),e("a",P,[a("pytorch官网下载界面"),s(n)])]),S,e("p",null,[e("a",C,[a("https://pytorch.org/"),s(n)])]),U,e("p",null,[a("访问"),e("a",A,[a("git官网"),s(n)]),a("直接下载，默认安装就可以。")]),D,e("p",null,[a("访问"),e("a",N,[a("ollama官网"),s(n)]),a("下载Windows版本的ollama，并安装。")]),B,e("p",null,[a("重启后，去"),e("a",G,[a("docker官网"),s(n)]),a("下载docker，默认安装就行。")]),I])}const V=r(c,[["render",W],["__file","01.html.vue"]]);export{V as default};
